{
  "name": "opencode-subagent-magazine",
  "version": "1.7.4",
  "description": "OpenCode TUI plugin monitoring sub-agent invocation status in real time",
  "type": "module",
  "types": "dist/index.d.ts",
  "exports": {
    "./server": {
      "import": "./dist/server.js",
      "types": "./dist/server.d.ts"
    },
    "./tui": {
      "import": "./tui/index.js"
    }
  },
  "files": [
    "dist",
    "tui",
    "install.mjs",
    "README.md"
  ],
  "bin": {
    "opencode-subagent-magazine": "install.mjs"
  },
  "scripts": {
    "build": "tsc --emitDeclarationOnly && node build.tui.mjs",
    "build:tui": "node build.tui.mjs",
    "typecheck": "tsc --noEmit",
    "test": "tsx --test tests/*.test.ts",
    "version": "node -e \"require('fs').writeFileSync('src/_version.ts','// auto-generated\\nexport const PLUGIN_VERSION='+JSON.stringify(require('./package.json').version)+';\\n')\"",
    "prepublishOnly": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "subagent",
    "subtask"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Hotakus/opencode-subagent-magazine.git"
  },
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.0",
    "@opencode-ai/sdk": ">=1.14.0",
    "@opencode/plugin": ">=2.0.0",
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode-ai/sdk": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opentui/core": "^0.5.8",
    "@opentui/solid": "^0.5.8",
    "@opencode-ai/plugin": "^1.14.50",
    "@opencode-ai/sdk": "^1.14.50",
    "@types/node": "^22.0.0",
    "esbuild": "^0.25.0",
    "esbuild-plugin-solid": "^0.5.0",
    "tsx": "^4.22.3",
    "typescript": "^5.8.0"
  }
}
